static int ResolvePhysicalVirtualKey(const KBDLLHOOKSTRUCT* data)
{
    if (!data)
    {
        return 0;
    }

    if (data->vkCode == VK_SHIFT)
    {
        const auto decoded = MapVirtualKeyW(data->scanCode, MAPVK_VSC_TO_VK_EX);
        return decoded == VK_LSHIFT || decoded == VK_RSHIFT ? static_cast<int>(decoded) : VK_SHIFT;
    }

    return static_cast<int>(data->vkCode);
}

KeyboardEvent ev;
ev.message = wParam;
ev.key = ResolvePhysicalVirtualKey(reinterpret_cast<KBDLLHOOKSTRUCT*>(lParam));

VirtualKey virtualKey = (VirtualKey)key;
if (RemappingHelper.IsModifierKey(virtualKey))
{
    RemoveExistingModifierVariant(virtualKey);
}

// With ev.key now decoded to RightShift or LeftShift, GetFormattedKeyList()
// must keep that concrete key name instead of collapsing back to generic Shift.

if (originalKey == VK_SHIFT)
{
    originalKeysWithModifiers.push_back(VK_LSHIFT);
    originalKeysWithModifiers.push_back(VK_RSHIFT);
}
else
{
    originalKeysWithModifiers.push_back(originalKey);
}

